package com.autoops.command.entity;import jakarta.persistence.*;import java.time.Instant;@Entity @Table(name="command_definitions")public class CommandDefinition{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false)private String name;private String description;private String category;private String action;@Column(name="resource_type")private String resourceType;@Column(name="command_template",nullable=false,columnDefinition="text")private String commandTemplate;@Column(name="parameters_schema",columnDefinition="jsonb")private String parametersSchema;@Column(name="risk_level",nullable=false)private String riskLevel="LOW";@Column(name="requires_approval",nullable=false)private boolean requiresApproval;@Column(nullable=false)private String status="PENDING";@Column(nullable=false)private String source="USER";@Column(name="created_by",nullable=false)private Long createdBy;@Column(name="created_at",nullable=false)private Instant createdAt=Instant.now();@Column(name="updated_at",nullable=false)private Instant updatedAt=Instant.now();public Long getId(){return id;}public String getName(){return name;}public void setName(String v){name=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public String getCategory(){return category;}public void setCategory(String v){category=v;}public String getCommandTemplate(){return commandTemplate;}public void setCommandTemplate(String v){commandTemplate=v;}public String getRiskLevel(){return riskLevel;}public void setRiskLevel(String v){riskLevel=v;}public boolean isRequiresApproval(){return requiresApproval;}public void setRequiresApproval(boolean v){requiresApproval=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public Long getCreatedBy(){return createdBy;}public void setCreatedBy(Long v){createdBy=v;}}
